public class MergeTwoSortedLists {

    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    // ---- 方法 1：迭代（面试首选） ----
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode dummy = new ListNode(0);   // 哑节点：消除头节点特判
        ListNode curr = dummy;
        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) {
                curr.next = list1;          // 接 list1 的当前节点
                list1 = list1.next;
            } else {
                curr.next = list2;          // 接 list2 的当前节点
                list2 = list2.next;
            }
            curr = curr.next;
        }
        // 剩余链表直接接上（已有序）
        curr.next = (list1 != null) ? list1 : list2;
        return dummy.next;                  // 跳过哑节点
    }

    // ---- 方法 2：递归 ----
    public ListNode mergeTwoListsRecursive(ListNode list1, ListNode list2) {
        if (list1 == null) return list2;
        if (list2 == null) return list1;
        if (list1.val <= list2.val) {
            list1.next = mergeTwoListsRecursive(list1.next, list2);
            return list1;
        } else {
            list2.next = mergeTwoListsRecursive(list1, list2.next);
            return list2;
        }
    }

    public static void main(String[] args) {
        MergeTwoSortedLists s = new MergeTwoSortedLists();

        // list1: 1 -> 2 -> 4
        ListNode l1 = new ListNode(1);
        l1.next = new ListNode(2);
        l1.next.next = new ListNode(4);

        // list2: 1 -> 3 -> 4
        ListNode l2 = new ListNode(1);
        l2.next = new ListNode(3);
        l2.next.next = new ListNode(4);

        ListNode merged = s.mergeTwoLists(l1, l2);
        for (ListNode p = merged; p != null; p = p.next) {
            System.out.print(p.val + " ");
        }
        // 输出: 1 1 2 3 4 4
    }
}
